import{_ as s,a0 as r,w as p,s as d,ao as o,I as i,x as t,a1 as e,A as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"Linux 用户的手边工具：Guide to Linux | LCTT x X-CMD","titleTemplate":false,"description":"Linux 用户的手边工具：Guide to Linux | LCTT (201711) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 用户的手边工具：Guide to Linux | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 用户的手边工具：Guide to Linux | LCTT (201711) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201711/20170825 Guide to Linux App Is a Handy Tool for Every Level of Linux User","title":"Linux 用户的手边工具：Guide to Linux","tag":"201711","desc":""},"relativePath":"201711/20170825 Guide to Linux App Is a Handy Tool for Every Level of Linux User.md","filePath":"[post].md"}'),x={name:"201711/20170825 Guide to Linux App Is a Handy Tool for Every Level of Linux User.md"};function m(a,l,L,f,w,g){const n=r("Link");return p(),d("div",null,[l[28]||(l[28]=o('<h1 id="linux-用户的手边工具-guide-to-linux" tabindex="-1">Linux 用户的手边工具：Guide to Linux <a class="header-anchor" href="#linux-用户的手边工具-guide-to-linux" aria-label="Permalink to “Linux 用户的手边工具：Guide to Linux”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/guide-to-linux.png?itok=AAcrxjjc" alt="Guide to Linux" title="Guide to Linux"></p><blockquote><p>“Guide to Linux” 这个应用并不完美，但它是一个非常好的工具，可以帮助你学习 Linux 命令。</p></blockquote><p>还记得你初次使用 Linux 时的情景吗？对于有些人来说，他的学习曲线可能有些挑战性。比如，在 <code>/usr/bin</code> 中能找到许多命令。在我目前使用的 Elementary OS 系统中，命令的数量是 1944 个。当然，这并不全是真实的命令（或者，我会使用到的命令数量），但这个数目是很多的。</p><p>正因为如此（并且不同平台不一样），现在，新用户（和一些已经熟悉的用户）需要一些帮助。</p><p>对于每个管理员来说，这些技能是必须具备的：</p><ul><li>熟悉平台</li><li>理解命令</li><li>编写 Shell 脚本</li></ul>',7)),i("p",null,[l[1]||(l[1]=t("当你寻求帮助时，有时，你需要去“阅读那些该死的手册”（Read the Fine/Freaking/Funky Manual，LCTT 译注：一个网络用语，简写为 RTFM），但是当你自己都不知道要找什么的时候，它就没办法帮到你了。在那个时候，你就会为你拥有像 ",-1)),e(n,{href:"https://play.google.com/store/apps/details?id=com.essence.linuxcommands"},{default:u(()=>[...l[0]||(l[0]=[t("Guide to Linux",-1)])]),_:1}),l[2]||(l[2]=t(" 这样的手机应用而感到高兴。",-1))]),l[29]||(l[29]=o('<p>不像你在 Linux.com 上看到的那些大多数的内容，这篇文章只是介绍一个 Android 应用的。为什么呢？因为这个特殊的 应用是用来帮助用户学习 Linux 的。</p><p>而且，它做的很好。</p><p>关于这个应用我清楚地告诉你 —— 它并不完美。Guide to Linux 里面充斥着很烂的英文，糟糕的标点符号，并且（如果你是一个纯粹主义者），它从来没有提到过 GNU。在这之上，它有一个特别的功能（通常它对用户非常有用）功能不是很有用（LCTT 译注：是指终端模拟器，后面会详细解释）。除此之外，我敢说 Guide to Linux 可能是 Linux 平台上最好的一个移动端的 “口袋指南”。</p><p>对于这个应用，你可能会喜欢它的如下特性：</p><ul><li>离线使用</li><li>Linux 教程</li><li>基础的和高级的 Linux 命令的详细介绍</li><li>包含了命令示例和语法</li><li>专用的 Shell 脚本模块</li></ul><p>除此以外，Guide to Linux 是免费提供的（尽管里面有一些广告）。如果你想去除广告，它有一个应用内的购买，（$2.99 USD/年）可以去消除广告。</p><p>让我们来安装这个应用，来看一看它的构成。</p><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h3><p>像所有的 Android 应用一样，安装 Guide to Linux 是非常简单的。按照以下简单的几步就可以安装它了：</p><ol><li>打开你的 Android 设备上的 Google Play 商店</li><li>搜索 Guide to Linux</li><li>找到 Essence Infotech 的那个，并轻触进入</li><li>轻触 Install</li><li>允许安装</li></ol><p>安装完成后，你可以在你的<ruby>应用抽屉<rt>App Drawer</rt></ruby>或主屏幕上（或者两者都有）上找到它去启动 Guide to Linux 。轻触图标去启动这个应用。</p><h3 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to “使用”">​</a></h3><p>让我们看一下 Guide to Linux 的每个功能。我发现某些功能比其它的更有帮助，或许你的体验会不一样。在我们分别讲解之前，我将重点提到其界面。开发者在为这个应用创建一个易于使用的界面方面做的很好。</p><p>从主窗口中（图 1），你可以获取四个易于访问的功能。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/floated_images/public/guidetolinux1.jpg?itok=UJhPP80J" alt="Guide to Linux main window" title="Guide to Linux main window"></p>',15)),i("p",null,[i("em",null,[l[4]||(l[4]=t("图 1： The Guide to Linux 主窗口。",-1)),e(n,{href:"https://www.linux.com/licenses/category/used-permission"},{default:u(()=>[...l[3]||(l[3]=[t("已获授权",-1)])]),_:1})])]),l[30]||(l[30]=i("p",null,"轻触四个图标中的任何一个去启动一个功能，然后，准备去学习。",-1)),l[31]||(l[31]=i("h3",{id:"教程",tabindex:"-1"},[t("教程 "),i("a",{class:"header-anchor",href:"#教程","aria-label":"Permalink to “教程”"},"​")],-1)),l[32]||(l[32]=i("p",null,"让我们从这个应用教程的最 “新手友好” 的功能开始。打开“Tutorial”功能，然后，将看到该教程的欢迎部分，“Linux 操作系统介绍”（图 2）。",-1)),l[33]||(l[33]=i("p",null,[i("img",{src:"https://www.linux.com/sites/lcom/files/styles/floated_images/public/guidetolinux2.jpg?itok=LiJ8pHdS",alt:"The Tutorial",title:"The Tutorial"})],-1)),i("p",null,[i("em",null,[l[6]||(l[6]=t("图 2：教程开始。",-1)),e(n,{href:"https://www.linux.com/licenses/category/used-permission"},{default:u(()=>[...l[5]||(l[5]=[t("已获授权",-1)])]),_:1})])]),l[34]||(l[34]=i("p",null,"如果你轻触 “汉堡包菜单” （左上角的三个横线），显示了内容列表（图 3），因此，你可以在教程中选择任何一个可用部分。",-1)),l[35]||(l[35]=i("p",null,[i("img",{src:"https://www.linux.com/sites/lcom/files/styles/floated_images/public/guidetolinux3_0.jpg?itok=5nJNeYN-",alt:"Tutorial TOC",title:"Tutorial TOC"})],-1)),i("p",null,[i("em",null,[l[8]||(l[8]=t("图 3：教程的内容列表。",-1)),e(n,{href:"https://www.linux.com/licenses/category/used-permission"},{default:u(()=>[...l[7]||(l[7]=[t("已获授权",-1)])]),_:1})])]),l[36]||(l[36]=i("p",null,"如果你现在还没有注意到，Guide to Linux 教程部分是每个主题的一系列短文的集合。短文包含图片和链接（有时候），链接将带你到指定的 web 网站（根据主题的需要）。这里没有交互，仅仅只能阅读。但是，这是一个很好的起点，由于开发者在描述各个部分方面做的很好（虽然有语法问题）。",-1)),l[37]||(l[37]=i("p",null,"尽管你可以在窗口的顶部看到一个搜索选项，但是，我还是没有发现这一功能的任何效果 —— 但是，你可以试一下。",-1)),l[38]||(l[38]=i("p",null,"对于 Linux 新手来说，如果希望获得 Linux 管理的技能，你需要去阅读整个教程。完成之后，转到下一个主题。",-1)),l[39]||(l[39]=i("h3",{id:"命令",tabindex:"-1"},[t("命令 "),i("a",{class:"header-anchor",href:"#命令","aria-label":"Permalink to “命令”"},"​")],-1)),l[40]||(l[40]=i("p",null,"命令功能类似于手机上的 man 页面一样，是大量的频繁使用的 Linux 命令。当你首次打开它，欢迎页面将详细解释使用命令的益处。",-1)),l[41]||(l[41]=i("p",null,"读完之后，你可以轻触向右的箭头（在屏幕底部）或轻触 “汉堡包菜单” ，然后从侧边栏中选择你想去学习的其它命令。（图 4）",-1)),l[42]||(l[42]=i("p",null,[i("img",{src:"https://www.linux.com/sites/lcom/files/styles/floated_images/public/guidetolinux4.jpg?itok=Rmzfb8Or",alt:"Commands",title:"Commands"})],-1)),i("p",null,[i("em",null,[l[10]||(l[10]=t("图 4：命令侧边栏允许你去查看列出的命令。",-1)),e(n,{href:"https://www.linux.com/licenses/category/used-permission"},{default:u(()=>[...l[9]||(l[9]=[t("已获授权",-1)])]),_:1})])]),l[43]||(l[43]=i("p",null,"轻触任意一个命令，你可以阅读这个命令的解释。每个命令解释页面和它的选项都提供了怎么去使用的示例。",-1)),l[44]||(l[44]=i("h3",{id:"shell-脚本",tabindex:"-1"},[t("Shell 脚本 "),i("a",{class:"header-anchor",href:"#shell-脚本","aria-label":"Permalink to “Shell 脚本”"},"​")],-1)),l[45]||(l[45]=i("p",null,"在这个时候，你开始熟悉 Linux 了，并对命令已经有一定程序的掌握。现在，是时候去熟悉 shell 脚本了。这个部分的设置方式与教程部分和命令部分相同。",-1)),l[46]||(l[46]=i("p",null,"你可以打开内容列表的侧边栏，然后打开包含 shell 脚本教程的任意部分（图 5）。",-1)),l[47]||(l[47]=i("p",null,[i("img",{src:"https://www.linux.com/sites/lcom/files/styles/floated_images/public/guidetolinux-5-new.jpg?itok=EDlZ92IA",alt:"Shell Script",title:"Shell Script"})],-1)),i("p",null,[i("em",null,[l[12]||(l[12]=t("图 5：Shell 脚本节看上去很熟悉。",-1)),e(n,{href:"https://www.linux.com/licenses/category/used-permission"},{default:u(()=>[...l[11]||(l[11]=[t("已获授权",-1)])]),_:1})])]),l[48]||(l[48]=i("p",null,"开发者在解释如何最大限度地利用 shell 脚本方面做的很好。对于任何有兴趣学习 shell 脚本细节的人来说，这是个很好的起点。",-1)),l[49]||(l[49]=i("h3",{id:"终端",tabindex:"-1"},[t("终端 "),i("a",{class:"header-anchor",href:"#终端","aria-label":"Permalink to “终端”"},"​")],-1)),l[50]||(l[50]=i("p",null,"现在我们到了一个新的地方，开发者在这个应用中包含了一个终端模拟器。遗憾的是，当你在一个没有 “root” 权限的 Android 设备上安装这个应用时，你会发现你被限制在一个只读文件系统中，在那里，大部分命令根本无法工作。但是，我在一台 Pixel 2 （通过 Android 应用商店）安装的 Guide to Linux 中，可以使用更多的这个功能（还只是较少的一部分）。在一台 OnePlus 3 （非 root 过的）上，不管我改变到哪个目录，我都是得到相同的错误信息 “permission denied”，甚至是一个简单的命令也如此。",-1)),l[51]||(l[51]=i("p",null,"在 Chromebook 上，不管怎么操作，它都是正常的（图 6）。可以说，它可以一直很好地工作在一个只读操作系统中（因此，你不能用它进行真正的工作或创建新文件）。",-1)),l[52]||(l[52]=i("p",null,[i("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/guidetolinux6_0.jpg?itok=cVENH5lM",alt:"Permission denied",title:"Permission denied"})],-1)),i("p",null,[i("em",null,[l[14]||(l[14]=t("图 6： 可以完美地（可以这么说）用一个终端模拟器去工作。",-1)),e(n,{href:"https://www.linux.com/licenses/category/used-permission"},{default:u(()=>[...l[13]||(l[13]=[t("已获授权",-1)])]),_:1})])]),l[53]||(l[53]=i("p",null,"记住，这并不是真实的成熟终端，但却是一个新用户去熟悉终端是怎么工作的一种方法。遗憾的是，大多数用户只会发现自己对这个工具的终端功能感到沮丧，仅仅是因为，它们不能使用他们在其它部分学到的东西。开发者可能将这个终端功能打造成了一个 Linux 文件系统沙箱，因此，用户可以真实地使用它去学习。每次用户打开那个工具，它将恢复到原始状态。这只是我一个想法。",-1)),l[54]||(l[54]=i("h3",{id:"写在最后",tabindex:"-1"},[t("写在最后… "),i("a",{class:"header-anchor",href:"#写在最后","aria-label":"Permalink to “写在最后…”"},"​")],-1)),l[55]||(l[55]=i("p",null,"尽管终端功能被一个只读文件系统所限制（几乎到了没法使用的程序），Guide to Linux 仍然是一个新手学习 Linux 的好工具。在 guide to Linux 中，你将学习关于 Linux、命令、和 shell 脚本的很多知识，以便在你安装你的第一个发行版之前，让你学习 Linux 有一个好的起点。",-1)),l[56]||(l[56]=i("hr",null,null,-1)),i("p",null,[l[16]||(l[16]=t("via: ",-1)),e(n,{href:"https://www.linux.com/learn/intro-to-linux/2017/8/guide-linux-app-handy-tool-every-level-linux-user"},{default:u(()=>[...l[15]||(l[15]=[t("https://www.linux.com/learn/intro-to-linux/2017/8/guide-linux-app-handy-tool-every-level-linux-user",-1)])]),_:1})]),i("p",null,[l[20]||(l[20]=t("作者：",-1)),e(n,{href:"https://www.linux.com/users/jlwallen"},{default:u(()=>[...l[17]||(l[17]=[t("JACK WALLEN",-1)])]),_:1}),l[21]||(l[21]=t(" 译者：",-1)),e(n,{href:"https://github.com/qhwdw"},{default:u(()=>[...l[18]||(l[18]=[t("qhwdw",-1)])]),_:1}),l[22]||(l[22]=t(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:u(()=>[...l[19]||(l[19]=[t("wxy",-1)])]),_:1})]),i("p",null,[l[25]||(l[25]=t("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...l[23]||(l[23]=[t("LCTT",-1)])]),_:1}),l[26]||(l[26]=t(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:u(()=>[...l[24]||(l[24]=[t("Linux中国",-1)])]),_:1}),l[27]||(l[27]=t(" 荣誉推出",-1))])])}const G=s(x,[["render",m]]);export{y as __pageData,G as default};
